use settlement_gate::{authorize, broadword};

fn expected(fee: u64) -> (u64, u64) {
    let mut active = 0;
    let mut sum = 0;
    let mut i = 0;
    while i < 8 {
        let b = (fee >> (8 * i)) & 0xff;
        if b != 0 { active += 1; }
        sum += b;
        i += 1;
    }
    (active, sum)
}

#[test]
fn every_byte_value_in_every_position() {
    for pos in 0..8 {
        for b in 0..=255u64 {
            let fee = b << (8 * pos);
            let (active, sum) = expected(fee);
            assert_eq!(broadword::count_nz_bytes(fee), active);
            assert_eq!(broadword::sum_bytes(fee), sum);
            assert_eq!(broadword::u_nz8(fee), if b == 0 { 0 } else { 0x80 << (8 * pos) });
        }
    }
}

#[test]
fn structured_words_and_policy() {
    let values = [0, 1, u64::MAX, 0x8080808080808080, 0x0101010101010101,
        0x0123456789abcdef, 0xfedcba9876543210, 0x8000000000000000];
    for &fee in &values {
        let (active, sum) = expected(fee);
        assert_eq!(broadword::count_nz_bytes(fee), active);
        assert_eq!(broadword::sum_bytes(fee), sum);
        let amount = u64::MAX;
        let debit = amount / 2 + 256 * active + sum;
        assert!(debit <= u64::MAX);
        assert_eq!(authorize(debit, amount, fee).unwrap().total_debit, debit);
        if debit < u64::MAX { assert!(authorize(debit - 1, amount, fee).is_none()); }
    }
}
